import 'test_case.dart';

/// Result of evaluating a single test case.
class EvaluationResult {
  const EvaluationResult({
    required this.testCase,
    required this.actualFacts,
    required this.actualSoap,
    required this.errors,
    required this.metrics,
    required this.durationMs,
  });

  /// The test case that was evaluated.
  final TestCase testCase;

  /// Actual facts extracted by the pipeline.
  final Map<String, dynamic> actualFacts;

  /// Actual SOAP note generated by the pipeline.
  final String actualSoap;

  /// List of errors/discrepancies found.
  final List<EvaluationError> errors;

  /// Computed metrics for this test case.
  final TestCaseMetrics metrics;

  /// Pipeline execution duration in milliseconds.
  final int durationMs;

  /// Overall pass/fail based on error severity.
  bool get passed =>
      !errors.any((e) => e.severity == ErrorSeverity.critical) &&
      !errors.any((e) => e.severity == ErrorSeverity.major);

  /// Count errors by severity.
  int countBySeverity(ErrorSeverity severity) =>
      errors.where((e) => e.severity == severity).length;

  Map<String, dynamic> toJson() => {
        'testCaseId': testCase.id,
        'passed': passed,
        'durationMs': durationMs,
        'metrics': metrics.toJson(),
        'errors': errors.map((e) => e.toJson()).toList(),
        'errorCounts': {
          'critical': countBySeverity(ErrorSeverity.critical),
          'major': countBySeverity(ErrorSeverity.major),
          'minor': countBySeverity(ErrorSeverity.minor),
          'info': countBySeverity(ErrorSeverity.info),
        },
        'actualFacts': actualFacts,
        'actualSoap': actualSoap,
      };
}

/// Metrics computed for a single test case.
class TestCaseMetrics {
  const TestCaseMetrics({
    required this.fieldMetrics,
    required this.evidenceCoverage,
    required this.hallucinationCount,
    required this.coherenceScore,
  });

  /// Precision/recall for each clinical field.
  final Map<String, FieldMetrics> fieldMetrics;

  /// Percentage of claims with valid evidence [0.0-1.0].
  final double evidenceCoverage;

  /// Number of hallucinated claims detected.
  final int hallucinationCount;

  /// Internal coherence score [0.0-1.0].
  final double coherenceScore;

  Map<String, dynamic> toJson() => {
        'fields': fieldMetrics.map((k, v) => MapEntry(k, v.toJson())),
        'evidenceCoverage': evidenceCoverage,
        'hallucinationCount': hallucinationCount,
        'coherenceScore': coherenceScore,
      };
}

/// Precision and recall metrics for a single field.
class FieldMetrics {
  const FieldMetrics({
    required this.precision,
    required this.recall,
    this.f1,
    this.truePositives = 0,
    this.falsePositives = 0,
    this.falseNegatives = 0,
  });

  /// Precision = TP / (TP + FP).
  final double precision;

  /// Recall = TP / (TP + FN).
  final double recall;

  /// F1 score = 2 * (P * R) / (P + R).
  final double? f1;

  final int truePositives;
  final int falsePositives;
  final int falseNegatives;

  factory FieldMetrics.compute({
    required int truePositives,
    required int falsePositives,
    required int falseNegatives,
  }) {
    final precision = truePositives + falsePositives == 0
        ? 1.0
        : truePositives / (truePositives + falsePositives);
    final recall = truePositives + falseNegatives == 0
        ? 1.0
        : truePositives / (truePositives + falseNegatives);
    final f1 = precision + recall == 0
        ? 0.0
        : 2 * precision * recall / (precision + recall);

    return FieldMetrics(
      precision: precision,
      recall: recall,
      f1: f1,
      truePositives: truePositives,
      falsePositives: falsePositives,
      falseNegatives: falseNegatives,
    );
  }

  Map<String, dynamic> toJson() => {
        'precision': precision,
        'recall': recall,
        if (f1 != null) 'f1': f1,
        'tp': truePositives,
        'fp': falsePositives,
        'fn': falseNegatives,
      };
}
